.breath-hourglass.active-inhale .hourglass-sand,.breath-hourglass.active-hold .hourglass-sand,.breath-hourglass.active-exhale .hourglass-sand{animation:sand-glow 1.6s ease-in-out infinite alternate}
.breath-hourglass{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;width:260px;height:300px;color:#fff}
.breath-hourglass .breath-label{font-size:28px;font-weight:900;letter-spacing:.02em}.breath-hourglass .breath-count{font-size:50px;line-height:1;font-family:Georgia,serif;margin-top:8px}.breath-hourglass .breath-sub{font-size:12px;letter-spacing:.16em;text-transform:uppercase;opacity:.78;margin-top:9px}
@keyframes sand-stream{0%,100%{transform:scaleY(.65);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}}
@keyframes sand-glow{from{filter:saturate(.85) brightness(.92)}to{filter:saturate(1.2) brightness(1.08)}}
@media(prefers-reduced-motion:reduce){.hourglass-sand,.hourglass-stream{transition:none;animation:none!important}}
</style>
<section class="card breath-card" id="breath-practice" data-inhale="<?= (int)$exercise['inhale_seconds'] ?>" data-hold="<?= (int)$exercise['hold_seconds'] ?>" data-exhale="<?= (int)$exercise['exhale_seconds'] ?>" data-default-cycles="<?= (int)$exercise['cycles'] ?>">
  <h2><?= e($exercise['title']) ?></h2>
  <p class="muted">A guided Scripture-centered rhythm for calm, focus and prayer.</p>
  <div class="breath-meta"><span>Inhale <?= (int)$exercise['inhale_seconds'] ?>s</span><?php if((int)$exercise['hold_seconds']>0):?><span>Hold <?= (int)$exercise['hold_seconds'] ?>s</span><?php endif;?><span>Exhale <?= (int)$exercise['exhale_seconds'] ?>s</span></div>
  <div class="breath-stage" aria-live="polite">
    <div class="breath-rings"><span></span><span></span></div>
    <div class="breath-hourglass" id="breath-orb" role="img" aria-label="Breathing hourglass">
      <div class="hourglass-visual" aria-hidden="true"><div class="hourglass-frame"><div class="hourglass-chamber top"><span class="hourglass-sand" id="hourglass-sand-top"></span></div><div class="hourglass-neck"><span class="hourglass-stream"></span></div><div class="hourglass-chamber bottom"><span class="hourglass-sand" id="hourglass-sand-bottom"></span></div></div></div>
      <span class="breath-label" id="breath-label">Ready</span><span class="breath-count" id="breath-count">—</span><span class="breath-sub" id="breath-cycle">Cycle 0</span>
    </div>
  </div>
  <div class="breath-progress" aria-label="Breathing session progress"><span id="breath-progress-bar"></span></div>
  <div class="breath-settings"><div><label for="pattern-select">Breathing pattern</label><select id="pattern-select"><option value="4,0,6">Peace · 4–6</option><option value="4,4,6">Steady · 4–4–6</option><option value="4,7,8">Rest · 4–7–8</option></select></div><div><label for="cycle-select">Session length</label><select id="cycle-select"><option value="2">2 cycles · quick reset</option><option value="5">5 cycles · calm focus</option><option value="10">10 cycles · extended prayer</option></select></div><button class="btn secondary" id="sound-toggle" type="button" aria-pressed="true">Gentle cues on</button></div>
  <div class="breath-actions"><button class="btn breath-btn" id="breath-start" type="button">Start breathing</button><button class="btn breath-btn secondary" id="breath-pause" type="button" disabled>Pause</button><button class="btn breath-btn secondary" id="breath-reset" type="button">Reset</button><button class="btn breath-btn secondary" id="breath-focus" type="button">Focus mode</button></div><button class="btn breath-btn secondary focus-exit" id="breath-focus-exit" type="button">Exit focus</button>
  <blockquote class="breath-scripture"><strong><?= e($exercise['scripture_reference']) ?></strong><br><?= e($exercise['prompt_text']) ?></blockquote>
  <div class="completion-panel" id="breath-complete"><strong>Peace be with you.</strong><span>Your guided breathing practice is complete.</span><form method="post" id="breath-complete-form"><input type="hidden" name="csrf" value="<?= e($_SESSION['practice_csrf']) ?>"><input type="hidden" name="action" value="breath"><input type="hidden" name="exercise_id" value="<?= (int)$exercise['id'] ?>"><input type="hidden" name="cycles" id="completed-cycles" value="<?= (int)$exercise['cycles'] ?>"><input type="hidden" name="duration" id="completed-duration" value="<?= ((int)$exercise['inhale_seconds']+(int)$exercise['hold_seconds']+(int)$exercise['exhale_seconds'])*(int)$exercise['cycles'] ?>"><button class="btn" type="submit">Save completed session</button></form></div>
</section>
<script>
(()=>{
 const root=document.getElementById('breath-practice'); if(!root)return;
 let inhale=Number(root.dataset.inhale)||4, hold=Number(root.dataset.hold)||0, exhale=Number(root.dataset.exhale)||6;
 const orb=document.getElementById('breath-orb'), sandTop=document.getElementById('hourglass-sand-top'), sandBottom=document.getElementById('hourglass-sand-bottom'), label=document.getElementById('breath-label'), count=document.getElementById('breath-count'), cycleText=document.getElementById('breath-cycle'), bar=document.getElementById('breath-progress-bar');
 const start=document.getElementById('breath-start'), pause=document.getElementById('breath-pause'), reset=document.getElementById('breath-reset'), select=document.getElementById('cycle-select'), pattern=document.getElementById('pattern-select'), sound=document.getElementById('sound-toggle'), complete=document.getElementById('breath-complete'), focus=document.getElementById('breath-focus'), focusExit=document.getElementById('breath-focus-exit');
 const cycleInput=document.getElementById('completed-cycles'), durationInput=document.getElementById('completed-duration');
 const allowed=[2,5,10], preferred=Number(root.dataset.defaultCycles)||5; select.value=String(allowed.includes(preferred)?preferred:5);
 let timer=null,running=false,paused=false,phaseIndex=0,secondsLeft=0,completed=0,soundOn=true;
 let phases=[]; const rebuildPhases=()=>{phases=[{name:'Inhale',seconds:inhale,cls:'active-inhale'},{name:'Hold',seconds:hold,cls:'active-hold'},{name:'Exhale',seconds:exhale,cls:'active-exhale'}].filter(p=>p.seconds>0)}; rebuildPhases();
 function totalSeconds(){return (inhale+hold+exhale)*Number(select.value)}
 function elapsed(){const full=inhale+hold+exhale; let phaseDone=0; for(let i=0;i<phaseIndex;i++)phaseDone+=phases[i].seconds; return completed*full+phaseDone+(phases[phaseIndex]?phases[phaseIndex].seconds-secondsLeft:0)}
 function cue(){if(!soundOn)return; try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=phaseIndex===0?440:phaseIndex===1?520:360;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.2)}catch(e){}}
 function render(){const p=phases[phaseIndex], progress=Math.min(1,elapsed()/Math.max(1,totalSeconds()));orb.className='breath-hourglass '+(running&&!paused&&p?p.cls:'');sandTop.style.setProperty('--sand-level',Math.max(0,100-(progress*100))+'%');sandBottom.style.setProperty('--sand-level',(progress*100)+'%');label.textContent=p&&running?(paused?'Paused':p.name):'Ready';count.textContent=p&&running?secondsLeft:'—';cycleText.textContent=`Cycle ${Math.min(completed+1,Number(select.value))} of ${select.value}`;bar.style.width=(progress*100)+'%'}
 function setPhase(index){phaseIndex=index;secondsLeft=phases[index].seconds;cue();render()}
 function tick(){if(!running||paused)return;secondsLeft--;if(secondsLeft<=0){if(phaseIndex<phases.length-1){setPhase(phaseIndex+1)}else{completed++;if(completed>=Number(select.value)){finish();return}else setPhase(0)}}else render()}
 function begin(){if(running&&!paused)return;complete.classList.remove('show');select.disabled=true;running=true;paused=false;start.textContent='Breathing…';start.disabled=true;pause.disabled=false;pause.textContent='Pause';if(secondsLeft<=0)setPhase(0);timer=setInterval(tick,1000)}
 function togglePause(){if(!running)return;paused=!paused;pause.textContent=paused?'Resume':'Pause';start.textContent=paused?'Paused':'Breathing…';if(!paused)cue();render()}
 function resetSession(){clearInterval(timer);timer=null;running=paused=false;phaseIndex=completed=secondsLeft=0;select.disabled=false;start.disabled=false;start.textContent='Start breathing';pause.disabled=true;pause.textContent='Pause';complete.classList.remove('show');orb.className='breath-hourglass';sandTop.style.setProperty('--sand-level','100%');sandBottom.style.setProperty('--sand-level','0%');label.textContent='Ready';count.textContent='—';cycleText.textContent='Cycle 0';bar.style.width='0%'}
 function finish(){clearInterval(timer);timer=null;running=false;paused=false;bar.style.width='100%';orb.className='breath-hourglass active-hold';sandTop.style.setProperty('--sand-level','0%');sandBottom.style.setProperty('--sand-level','100%');label.textContent='Complete';count.textContent='✓';cycleText.textContent=`${select.value} cycles`;start.disabled=true;pause.disabled=true;complete.classList.add('show');cycleInput.value=select.value;durationInput.value=totalSeconds();localStorage.setItem('dailybreath.breathe.'+new Date().toISOString().slice(0,10),'1');cue();if(navigator.vibrate)navigator.vibrate([80,60,80])}
 function setFocus(enabled){root.classList.toggle('breath-focus',enabled);document.body.style.overflow=enabled?'hidden':'';if(enabled)focusExit.focus();else focus.focus()}
 focus.addEventListener('click',()=>setFocus(true));focusExit.addEventListener('click',()=>setFocus(false));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&root.classList.contains('breath-focus'))setFocus(false)});
 start.addEventListener('click',begin);pause.addEventListener('click',togglePause);reset.addEventListener('click',resetSession);select.addEventListener('change',resetSession);pattern.addEventListener('change',()=>{if(running)return;[inhale,hold,exhale]=pattern.value.split(',').map(Number);root.dataset.inhale=inhale;root.dataset.hold=hold;root.dataset.exhale=exhale;rebuildPhases();resetSession()});sound.addEventListener('click',()=>{soundOn=!soundOn;sound.setAttribute('aria-pressed',String(soundOn));sound.textContent=soundOn?'Gentle cues on':'Gentle cues off'});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)togglePause()});render();
})();
</script>
<?php endif;?>
<?php if($section==='prayers'):?><section class="card"><h2>Prayers for this moment</h2><?php foreach($prayers as $prayer):?><article class="prayer"><strong><?= e($prayer['title']) ?></strong><p><?= e($prayer['prayer_text']) ?></p><small><?= e($prayer['scripture_reference']) ?></small></article><?php endforeach;?></section><?php endif;?>
<?php if($section==='journal'):?><section class="card"><div class="journal-head"><div><h2>Private Reflection Journal</h2><p class="muted">Your entries are encrypted before they are stored.</p></div><span class="journal-count"><?= count($journalEntries) ?> recent</span></div><p><strong>Today’s prompt:</strong> <?= e($prompt['prompt_text']??'What is God inviting you to notice today?') ?></p><form method="post" id="journal-form" autocomplete="off"><input type="hidden" name="csrf" value="<?= e($_SESSION['practice_csrf']) ?>"><input type="hidden" name="action" value="journal"><input type="hidden" name="prompt_id" value="<?= (int)($prompt['id']??0) ?>"><label for="journal-mood">Mood</label><input id="journal-mood" class="field" name="mood" maxlength="40" value="<?= e((string)($_POST['mood']??'')) ?>" placeholder="Peaceful, hopeful, uncertain…"><label for="journal-entry">Reflection</label><textarea id="journal-entry" class="field area" name="entry" maxlength="10000" required placeholder="Write privately here…"><?= e((string)($_POST['entry']??'')) ?></textarea><p class="privacy" id="journal-draft-status" role="status">Drafts stay on this device until you submit.</p><div class="submit-row"><button class="btn" type="submit">Submit private reflection</button><span class="privacy">🔒 Visible only through your Beyond ID</span></div></form></section><section class="card"><h2>Recent reflections</h2><?php if(!$journalEntries):?><p class="muted">Your submitted reflections will appear here.</p><?php endif;?><?php foreach($journalEntries as $entry):?><article class="entry"><div class="entry-top"><div><time><?= e(date('M j, Y · g:i a',strtotime((string)$entry['created_at']))) ?></time><?php if(trim((string)$entry['mood'])!==''):?> <span class="mood"><?= e($entry['mood']) ?></span><?php endif;?></div><form method="post" onsubmit="return confirm('Delete this private journal entry?')"><input type="hidden" name="csrf" value="<?= e($_SESSION['practice_csrf']) ?>"><input type="hidden" name="action" value="delete_journal"><input type="hidden" name="entry_id" value="<?= (int)$entry['id'] ?>"><button class="delete" type="submit">Delete</button></form></div><?php if(!empty($entry['prompt_text'])):?><small class="muted"><?= e($entry['prompt_text']) ?></small><?php endif;?><p><?= e($entry['content_plain']) ?></p></article><?php endforeach;?></section><?php endif;?>
<?php if($section==='challenge'&&$challenge):?><section class="card"><h2><?= e($challenge['title']) ?></h2><p><?= e($challenge['description']) ?></p><p class="muted"><?= e($challenge['scripture_reference']) ?></p><?php if(!empty($challenge['steps'])):?><ol><?php foreach($challenge['steps'] as $step):?><li><?= e($step) ?></li><?php endforeach;?></ol><?php endif;?><div class="progress"><span style="width:<?= min(100,round($progress/max(1,(int)$challenge['target_count'])*100)) ?>%"></span></div><p><?= $progress ?> of <?= (int)$challenge['target_count'] ?> days complete</p><form method="post"><input type="hidden" name="csrf" value="<?= e($_SESSION['practice_csrf']) ?>"><input type="hidden" name="action" value="challenge"><input type="hidden" name="challenge_id" value="<?= e((string)$challenge['id']) ?>"><input type="hidden" name="challenge_source" value="<?= ($challenge['source']??'')==='bundled_recovery_challenge'?'bundled':'database' ?>"><button class="btn" <?= $progress >= (int)$challenge['target_count']?'disabled':'' ?>><?= $progress >= (int)$challenge['target_count']?'Challenge complete':'Mark today complete' ?></button></form><p class="privacy">Progress is saved to your Beyond ID, including bundled recovery challenges.</p></section><?php endif;?></main><?php if($section==='journal'):?><script>(()=>{const form=document.getElementById('journal-form'),entry=document.getElementById('journal-entry'),mood=document.getElementById('journal-mood'),status=document.getElementById('journal-draft-status'),key='dailybreath.journal.draft';if(!form||!entry)return;try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft&&!entry.value&&!mood.value){entry.value=draft.entry||'';mood.value=draft.mood||'';if(draft.entry||draft.mood)status.textContent='Draft restored from this device.'}}catch(e){};const save=()=>{try{localStorage.setItem(key,JSON.stringify({entry:entry.value,mood:mood.value}))}catch(e){}};entry.addEventListener('input',save);mood.addEventListener('input',save);form.addEventListener('submit',()=>{try{localStorage.removeItem(key)}catch(e){}})})();</script><?php endif;?><?=dailybreath_web_scripts()?><script src="/assets/js/visitor-analytics.js" defer></script></body></html>
